const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".world{position:absolute;inset:0;overflow:hidden;border-radius:14px;outline:none;cursor:default;background:#e8dfe0}\n.world:focus-visible{box-shadow:inset 0 0 0 2px #ffffff,inset 0 0 0 4px #9bb0c8}\n.art{position:absolute;inset:0;width:100%;height:100%;display:block}\n.sk0{stop-color:#c4d2da}.sk1{stop-color:#dde3e6}.sk2{stop-color:#f3e4e2}.sk3{stop-color:#f9ece6}\n.gl0{stop-color:#fff6dc;stop-opacity:.95}.gl1{stop-color:#fff1d2;stop-opacity:.4}.gl2{stop-color:#fff1d2;stop-opacity:0}\n.gr0{stop-color:#f6ebe9}.gr1{stop-color:#ffffff}\n.tr0{stop-color:#fffdf0;stop-opacity:.95}.tr1{stop-color:#ffe7b4;stop-opacity:.85}\n.haze{opacity:.8}.halo{opacity:.9}.fog{opacity:.75}\n.towerRoof{fill:#8fa2a8}.towerWall{fill:#ecd9d6}.towerShade{fill:#dcc3c3}\n.roofS{fill:#f6f2f1}.roofE{fill:none;stroke:#d8c5c8;stroke-width:1.4;stroke-linecap:round}\n.far{fill:#efdcda;opacity:.75}\n.wallA{fill:#ecd3d1}.wallB{fill:#f1e0dc}\n.win{fill:#ffd58a}.winOff{fill:#d9c2c4}.winG{fill:#ffd58a;opacity:.4;filter:blur(2.2px)}\n.winBar{fill:none;stroke:#b98f6a;stroke-width:.7;opacity:.6}.winSm{fill:#ffd58a}\n.cone{opacity:.9}\n.lt0{fill:#ffe7a6;animation:twinkle 3.2s ease-in-out infinite}\n.lt1{fill:#fff6d6;animation:twinkle 4.4s ease-in-out infinite}\n.lt2{fill:#ffd88c;animation:twinkle 5.6s ease-in-out infinite}\n.starG{opacity:.95}.star{fill:#fff4b8}\n.ground{opacity:1}.track{fill:none;stroke:#eadadc;stroke-width:6;stroke-linecap:round;opacity:.7}\n.wire{fill:none;stroke:#b79a8a;stroke-width:.6;opacity:.7}\n.bulbG{fill:#ffd98a;opacity:.5;filter:blur(1.6px)}\n.bulb{fill:#fff1c4;animation:twinkle 3.6s ease-in-out infinite}\n.pShadow{fill:#b9a1ab;opacity:.35}\n.coatD{fill:#3e3239}.coatM{fill:#6b5560}.dressP{fill:#f0b7c0}.dressW{fill:#f6e8e8}\n.skin{fill:#f2d6c6}.hatD{fill:#3a2e34}.hairD{fill:#5b4540}\n.horse{fill:#6a4a3c}.mane{fill:none;stroke:#3f2b23;stroke-width:3;stroke-linecap:round}.tail{fill:none;stroke:#3f2b23;stroke-width:3;stroke-linecap:round}.legs{fill:none;stroke:#4d352c;stroke-width:2.4;stroke-linecap:round}\n.cabin{fill:#4a3b36}.cabinTop{fill:#3a2e2b}.wheel{fill:none;stroke:#2f2724;stroke-width:2.2}.hub{fill:#2f2724}\n.bk{filter:blur(2.6px);animation:twinkle 5s ease-in-out infinite}\n.bkW{fill:#ffe29a;opacity:.5}.bkP{fill:#ffd1da;opacity:.22}\n.frost{position:absolute;inset:0;pointer-events:none;opacity:0;transition:opacity .6s ease;\n  background:radial-gradient(ellipse at 50% 45%,#e6f0ff00 40%,#cfe0ff33 100%)}\n.world:hover .frost,.world:active .frost,.world:focus-visible .frost{opacity:1}\n.snow{position:absolute;inset:0;pointer-events:none;overflow:hidden}\n.fl{position:absolute;left:var(--x);top:0;width:var(--s);height:var(--s);opacity:var(--o);animation:fall var(--d) linear var(--dl) infinite;will-change:transform}\n.fl .sw{display:block;width:100%;height:100%;border-radius:50%;animation:sway var(--sw) ease-in-out infinite alternate;\n  background:radial-gradient(circle,#ffffff 0,#ffffff 46%,#ffffffcc 62%,#ffffff00 76%);box-shadow:0 0 .5cqw #8ea3b855}\n.fl.warm .sw{background:radial-gradient(circle,#fff6d8 0,#ffe39a 46%,#ffe39acc 62%,#ffe39a00 76%);box-shadow:0 0 .6cqw #e0b45a66}\n.fl.bl .sw{filter:blur(.5cqw)}\n.world:hover *,.world:active *,.world:focus-visible *{animation-play-state:paused}\n@keyframes fall{from{transform:translate3d(0,-8cqh,0)}to{transform:translate3d(var(--dx),108cqh,0)}}\n@keyframes sway{from{transform:translateX(calc(var(--a)*-1))}to{transform:translateX(var(--a))}}\n@keyframes twinkle{0%,100%{opacity:.35}50%{opacity:1}}\n@media (prefers-reduced-motion:reduce){.world *{animation-play-state:paused}}\n";
function S(el,tag,cls,attrs,...kids){return el(tag,{class:cls||null,...(attrs||{})},...kids);}
function rng(seed){let s=seed;return()=>{s=(s*1664525+1013904223)%4294967296;return s/4294967296;};}
function r1(n){return Math.round(n*10)/10;}

function stop(el,cls,off){return S(el,'stop',cls,{offset:off});}

function defs(el){
  return S(el,'defs',null,null,
    S(el,'linearGradient',null,{id:'sk',x1:0,y1:0,x2:0,y2:1},stop(el,'sk0','0'),stop(el,'sk1','.42'),stop(el,'sk2','.78'),stop(el,'sk3','1')),
    S(el,'radialGradient',null,{id:'gl',cx:.5,cy:.5,r:.5},stop(el,'gl0','0'),stop(el,'gl1','.55'),stop(el,'gl2','1')),
    S(el,'linearGradient',null,{id:'gr',x1:0,y1:0,x2:0,y2:1},stop(el,'gr0','0'),stop(el,'gr1','1')),
    S(el,'linearGradient',null,{id:'tr',x1:0,y1:0,x2:0,y2:1},stop(el,'tr0','0'),stop(el,'tr1','1')));
}

function windows(el,x,y,cols,rows,w,h,gx,gy,seed){
  const r=rng(seed),out=[];
  for(let i=0;i<cols;i++)for(let j=0;j<rows;j++){
    const lit=r()>.18,wx=x+i*(w+gx),wy=y+j*(h+gy);
    out.push(S(el,'rect','winG',{x:wx-2,y:wy-2,width:w+4,height:h+4,rx:2}));
    out.push(S(el,'rect',lit?'win':'winOff',{x:wx,y:wy,width:w,height:h,rx:1.2}));
    out.push(S(el,'path','winBar',{d:'M'+(wx+w/2)+' '+wy+'v'+h}));
  }
  return out;
}

function gable(el,x,y,w,h,gh,wall,cols,rows,seed){
  return S(el,'g',null,null,
    S(el,'rect',wall,{x:x,y:y,width:w,height:h}),
    S(el,'polygon','roofS',{points:(x-4)+','+(y+3)+' '+(x+w/2)+','+(y-gh)+' '+(x+w+4)+','+(y+3)}),
    S(el,'path','roofE',{d:'M'+(x-3)+' '+(y+4)+'Q'+(x+w/2)+' '+(y+9)+' '+(x+w+3)+' '+(y+4)}),
    ...windows(el,x+w/2-(cols*7+(cols-1)*4)/2,y+14,cols,rows,7,11,4,10,seed));
}

function tower(el){
  return S(el,'g','tower',null,
    S(el,'polygon','towerRoof',{points:'30,26 46,-14 62,26'}),
    S(el,'polygon','roofS',{points:'33,24 46,-8 59,24 54,22 46,0 38,22'}),
    S(el,'rect','towerWall',{x:32,y:26,width:28,height:150}),
    S(el,'rect','towerShade',{x:50,y:26,width:10,height:150}),
    S(el,'rect','roofS',{x:29,y:24,width:34,height:5,rx:2}),
    S(el,'rect','win',{x:41,y:44,width:10,height:16,rx:5}),
    S(el,'rect','win',{x:41,y:84,width:10,height:14,rx:5}),
    S(el,'rect','towerShade',{x:30,y:120,width:32,height:4}),
    S(el,'rect','win',{x:41,y:136,width:10,height:14,rx:5}));
}

function farRow(el){
  const r=rng(11),out=[];
  for(let i=0;i<7;i++){
    const x=70+i*26,h=52+r()*34;
    out.push(S(el,'rect','far',{x:x,y:228-h,width:22,height:h}),
      S(el,'polygon','far',{points:(x-2)+','+(228-h+2)+' '+(x+11)+','+(228-h-14)+' '+(x+24)+','+(228-h+2)}));
  }
  return S(el,'g','farRow',null,...out);
}

function tree(el){
  const r=rng(3),lights=[];
  for(let i=0;i<86;i++){
    const t=Math.pow(r(),.8),y=84+t*236,half=7+t*52,x=172+(r()*2-1)*half;
    lights.push(S(el,'circle','lt'+(i%3),{cx:r1(x),cy:r1(y),r:r1(.9+r()*1.5),style:{animationDelay:(-r()*5).toFixed(2)+'s'}}));
  }
  return S(el,'g','tree',null,
    S(el,'ellipse','halo',{cx:172,cy:215,rx:92,ry:150,fill:'url(#gl)'}),
    S(el,'polygon','cone',{points:'172,64 124,190 220,190',fill:'url(#tr)'}),
    S(el,'polygon','cone',{points:'172,96 112,254 232,254',fill:'url(#tr)'}),
    S(el,'polygon','cone',{points:'172,128 100,322 244,322',fill:'url(#tr)'}),
    ...lights,
    S(el,'circle','starG',{cx:172,cy:62,r:15,fill:'url(#gl)'}),
    S(el,'path','star',{d:'M172 50 L174.6 58.4 L183 58.6 L176.2 63.6 L178.8 72 L172 67 L165.2 72 L167.8 63.6 L161 58.6 L169.4 58.4 Z'}));
}

function person(el,x,y,s,coat,hat){
  return S(el,'g','ppl',{transform:'translate('+x+' '+y+') scale('+s+')'},
    S(el,'ellipse','pShadow',{cx:0,cy:1,rx:7,ry:1.8}),
    S(el,'path',coat,{d:'M-4.6 -23 Q0 -25 4.6 -23 L7 0 L-7 0 Z'}),
    S(el,'circle','skin',{cx:0,cy:-27,r:3.4}),
    hat?S(el,'path','hatD',{d:'M-4.4 -29.4 H4.4 L3.2 -36 H-3.2 Z'}):S(el,'path','hairD',{d:'M-3.6 -28 Q0 -33 3.6 -28 Q0 -30 -3.6 -28 Z'}));
}

function carriage(el){
  return S(el,'g','carr',null,
    S(el,'ellipse','pShadow',{cx:262,cy:398,rx:40,ry:3.4}),
    S(el,'g',null,{transform:'translate(232 372)'},
      S(el,'path','tail',{d:'M17 -6 Q27 -1 24 13'}),
      S(el,'rect','horse',{x:-18,y:-12,width:36,height:16,rx:8}),
      S(el,'path','horse',{d:'M-15 -7 L-21 -26 L-14 -31 L-7 -9 Z'}),
      S(el,'path','horse',{d:'M-21 -28 Q-31 -28 -32 -21 L-28 -18.5 Q-24 -22 -16 -22 L-14 -31 Z'}),
      S(el,'path','mane',{d:'M-14 -31 Q-9 -24 -7 -11'}),
      S(el,'path','legs',{d:'M-13 3 V24 M-6 3 V25 M9 3 V25 M15 3 V24'})),
    S(el,'path','legs',{d:'M250 368 L268 374'}),
    S(el,'rect','cabin',{x:268,y:354,width:32,height:26,rx:3}),
    S(el,'path','cabinTop',{d:'M264 356 Q284 340 304 356 Z'}),
    S(el,'rect','winSm',{x:273,y:360,width:9,height:9,rx:1.5}),
    S(el,'rect','winSm',{x:286,y:360,width:9,height:9,rx:1.5}),
    S(el,'circle','wheel',{cx:278,cy:391,r:8}),S(el,'circle','wheel',{cx:297,cy:391,r:8}),
    S(el,'circle','hub',{cx:278,cy:391,r:1.8}),S(el,'circle','hub',{cx:297,cy:391,r:1.8}));
}

function bulbs(el,x0,y0,x1,y1,n,sag,seed){
  const r=rng(seed),out=[];
  for(let i=0;i<=n;i++){
    const t=i/n,x=x0+(x1-x0)*t,y=y0+(y1-y0)*t+Math.sin(t*Math.PI)*sag;
    out.push(S(el,'circle','bulbG',{cx:r1(x),cy:r1(y),r:3.4}),
      S(el,'circle','bulb',{cx:r1(x),cy:r1(y),r:1.25,style:{animationDelay:(-r()*4).toFixed(2)+'s'}}));
  }
  return S(el,'g',null,null,S(el,'path','wire',{d:'M'+x0+' '+y0+' Q'+r1((x0+x1)/2)+' '+r1((y0+y1)/2+sag*2)+' '+x1+' '+y1}),...out);
}

function bokeh(el){
  const r=rng(41),out=[];
  for(let i=0;i<22;i++){
    const x=r()*300,y=r()*300,rad=3+r()*9,warm=r()<.88;
    out.push(S(el,'circle',warm?'bk bkW':'bk bkP',{cx:r1(x),cy:r1(y),r:r1(rad),style:{animationDelay:(-r()*6).toFixed(2)+'s'}}));
  }
  return S(el,'g','bokeh',null,...out);
}

function scene(el){
  return S(el,'svg','art',{viewBox:'0 30 300 350',preserveAspectRatio:'xMidYMid slice','aria-hidden':'true'},
    defs(el),
    S(el,'rect',null,{x:0,y:0,width:300,height:400,fill:'url(#sk)'}),
    S(el,'ellipse','haze',{cx:172,cy:240,rx:150,ry:190,fill:'url(#gl)'}),
    tower(el),
    farRow(el),
    gable(el,-6,202,68,112,26,'wallA',3,3,5),
    gable(el,60,184,50,132,30,'wallB',2,4,9),
    gable(el,108,218,40,100,22,'wallA',2,3,13),
    gable(el,238,176,68,150,34,'wallB',3,4,17),
    gable(el,214,238,28,84,16,'wallA',1,3,23),
    S(el,'path','ground',{d:'M0 296 Q150 282 300 296 V400 H0 Z',fill:'url(#gr)'}),
    S(el,'path','track',{d:'M120 400 Q150 350 168 316 M176 400 Q184 360 186 318'}),
    bulbs(el,8,206,100,200,9,5,31),
    bulbs(el,104,212,150,226,6,4,32),
    bulbs(el,242,184,300,176,7,5,33),
    S(el,'g',null,{transform:'translate(0 8)'},tree(el)),
    S(el,'ellipse','fog',{cx:172,cy:330,rx:130,ry:40,fill:'url(#gl)'}),
    S(el,'g',null,{transform:'translate(0 -16)'},
      person(el,150,338,.5,'coatM',false),person(el,162,340,.5,'dressP',false),
    person(el,52,366,1.05,'coatD',true),person(el,67,364,1,'coatM',false),person(el,85,368,1.08,'dressW',false),person(el,102,364,1.02,'coatD',true),
    person(el,208,346,.74,'dressP',false),person(el,220,344,.74,'coatM',true),
    ),
    S(el,'g',null,{transform:'translate(0 -42)'},carriage(el)),
    bokeh(el));
}

function flakes(el){
  const r=rng(21),out=[];
  const layers=[
    {n:66,s:[.7,1.5],d:[12,18],o:[.6,.95],a:[1,3],w:.12},
    {n:44,s:[1.5,2.5],d:[8,12],o:[.8,1],a:[2,5],w:.2},
    {n:20,s:[3,5],d:[5.5,8],o:[.45,.8],a:[3,8],w:.3,bl:true}
  ];
  const lerp=(a,b)=>a+(b-a)*r();
  for(const L of layers){
    for(let i=0;i<L.n;i++){
      const d=lerp(L.d[0],L.d[1]),warm=r()<L.w;
      const vars='--x:'+(r()*100).toFixed(1)+'%;--s:'+lerp(L.s[0],L.s[1]).toFixed(2)+'cqw;--d:'+d.toFixed(1)+'s;--dl:'+(-r()*d).toFixed(1)+'s;'
        +'--dx:'+((r()*2-1)*9).toFixed(1)+'cqw;--o:'+lerp(L.o[0],L.o[1]).toFixed(2)+';--sw:'+lerp(2.4,5.6).toFixed(1)+'s;--a:'+lerp(L.a[0],L.a[1]).toFixed(1)+'cqw';
      out.push(S(el,'span','fl'+(warm?' warm':'')+(L.bl?' bl':''),{style:vars},S(el,'i','sw')));
    }
  }
  return S(el,'div','snow',{'aria-hidden':'true'},...out);
}

function mount(ctx){
  const {root,el}=ctx;
  root.append(el('div',{class:'world',role:'img',tabindex:'0',
    'aria-label':'下雪的小镇：雪在飘落。鼠标移上来、按住或聚焦时，时间会静止；移开后继续落下。'},
    scene(el),
    S(el,'div','frost',{'aria-hidden':'true'}),
    flakes(el)));
}

const RUNTIME_BUILD='v50-r22-theme-20261102';
const INFRA_CSS=`:host{display:block;width:100%;height:100%}*{box-sizing:border-box}.card{width:100%;height:100%;position:relative;container:card / size;min-width:0;min-height:0;overflow:auto}button,input,textarea,select{font:inherit}button{cursor:pointer;touch-action:manipulation}.infra-panel{position:absolute;inset:0;z-index:100;display:grid;grid-template-rows:auto minmax(0,1fr) auto;gap:10px;padding:12px;background:var(--panel-paper);color:var(--ink);overflow:hidden;font:13px/1.4 system-ui}.infra-head{display:flex;align-items:center;justify-content:space-between;gap:8px}.infra-content{overflow:auto;min-height:0}.infra-actions{display:flex;gap:6px;flex-wrap:wrap}.infra-panel button{border:1px solid var(--line);border-radius:8px;padding:7px 10px;background:var(--button-paper);color:inherit}.infra-panel button[data-primary]{background:var(--accent);color:var(--on-accent)}.infra-form{display:grid;gap:10px}.infra-form label{display:grid;gap:4px}.infra-form input:not([type=checkbox]),.infra-form textarea,.infra-form select{width:100%;min-width:0;padding:8px;border:1px solid var(--line);border-radius:7px;background:var(--panel-paper);color:inherit}.infra-error{color:var(--danger);font-size:12px}.infra-form textarea{min-height:65px}`;
export default class Card extends HTMLElement{
 constructor(){super();this.attachShadow({mode:'open'});this.state={};this.ui={};this.queue=Promise.resolve();this.epoch=0;this.pending=0;}
 set tabbitHost(h){this.host=h;if(this.isConnected)this.load();}
 connectedCallback(){if(this.host)this.load();}
 disconnectedCallback(){this.epoch++;this.stop();}
 destroy(){this.disconnectedCallback();}
 stop(){this.cleanup?.();this.cleanup=null;clearInterval(this.dateTimer);this.dateTimer=null;}
 day(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
 async load(){const e=++this.epoch;this.stop();try{const r=await this.host.storage.get('state');if(e!==this.epoch||!this.isConnected)return;this.state=r.entry?.value||{};if(typeof initialize==='function'){const original=JSON.stringify(this.state);const prepared=initialize(JSON.parse(original));if(!prepared||typeof prepared!=='object')throw Error('initialize must return state');if(JSON.stringify(prepared)!==original){await this.host.storage.set('state',prepared);if(e!==this.epoch||!this.isConnected)return;this.state=prepared;}}this.ui={};this.saveError='';this.render();this.lastDay=this.day();this.dateTimer=setInterval(()=>{if(this.day()!==this.lastDay&&!this.pending){this.lastDay=this.day();this.render();}},1000);}catch(error){if(e===this.epoch)this.showError(error);}}
 contextShape(){const c=this.host.ctx;return JSON.stringify(Object.fromEntries(Object.entries(c).filter(([k])=>k!=='colors')));}
 updateTabbitContext(){if(!this.host)return;const shape=this.contextShape();if(shape!==this.renderedContext){this.render();return;}if(this.colorListener)this.colorListener(this.host.ctx.colors);}
 showError(error){this.saveError=String(error?.message||error);if(this.isConnected)this.render();}
 update(fn){const e=this.epoch;this.pending++;const job=this.queue.catch(()=>{}).then(async()=>{if(e!==this.epoch)throw Error('Card context changed');const next=JSON.parse(JSON.stringify(fn(JSON.parse(JSON.stringify(this.state)))));await this.host.storage.set('state',next);if(e===this.epoch){this.state=next;this.saveError='';}return true;});this.queue=job;return job.catch(error=>{if(e===this.epoch)this.saveError=String(error?.message||error);throw error;}).finally(()=>{this.pending--;if(e===this.epoch&&this.isConnected)this.render();});}
 commit(fn,nextUi={}){if(this.committing)return Promise.resolve(false);this.committing=true;return this.update(fn).then(()=>{Object.assign(this.ui,nextUi);return true;}).finally(()=>{this.committing=false;if(this.isConnected)this.render();});}
 async runAsync(key,work){
 const jobs=this.ui.jobs||(this.ui.jobs={});if(jobs[key]?.status==='loading')return false;
 const e=this.epoch,entry={status:'loading'};jobs[key]=entry;
 const job=Promise.resolve().then(()=>{if(e===this.epoch&&this.isConnected)this.render();return work();});
 try{const data=await job;if(e!==this.epoch||jobs!==this.ui.jobs)return false;jobs[key]={status:'ok',data};return true;}
 catch(error){if(e===this.epoch&&jobs===this.ui.jobs)jobs[key]={status:'error',error:String(error?.message||error)};return false;}
 finally{if(e===this.epoch&&this.isConnected)this.render();}
 }
 async fetchSource(id){const r=await this.host.fetchData(id);if(r?.status!=='ok')throw Error(r?.errorCode||r?.message||'数据源获取失败');const d=r.data;if(d===null||typeof d!=='object'||Object.keys(d).length===0)throw Error('暂未获取到有效数据');return d;}
